/* HEXA BATTLEGROUNDS upgrade — PART 18 OF 28. Only for databases that already ran setup part-01…; Run in order. Safe to re-run. */ insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('mission-pic-4', 'picture', 'mission', 'Picture Riddles', 'picture', 1, array['any','learning','social','office','coffee','public']::text[], 'Each teammate holds one picture riddle: two pictures make one word. Solve all three.', '{"scout":{"title":"Picture 1","body":"🦷 + 🖌️","mono":false,"big":true},"decoder":{"title":"Picture 2","body":"🛏️ + 🪨","mono":false,"big":true},"intel":{"title":"Picture 3","body":"🧠 + ⛈️","mono":false,"big":true}}'::jsonb, '[{"label":"Picture 1 (Scout)","accept":["TOOTHBRUSH"]},{"label":"Picture 2 (Decoder)","accept":["BEDROCK"]},{"label":"Picture 3 (Intel)","accept":["BRAINSTORM"]}]'::jsonb, false, 3, 200, 'Say each emoji out loud and join the words: 🪜 + 👨 = STEP + FATHER.', 'TOOTHBRUSH: tooth + brush | BEDROCK: bed + rock | BRAINSTORM: brain + storm', null, 25, 'published'), ('recovery-pic-0', 'picture', 'recovery', 'Picture Riddles', 'picture', 1, array['any']::text[], 'Get back on your feet: two pictures make one word. Solve all three.', '{"scout":{"title":"Picture 1","body":"☀️ + 🌻","mono":false,"big":true},"decoder":{"title":"Picture 2","body":"🔑 + 🎹","mono":false,"big":true},"intel":{"title":"Picture 3","body":"☁️ + 🖥️","mono":false,"big":true}}'::jsonb, '[{"label":"Picture 1 (Scout)","accept":["SUNFLOWER"]},{"label":"Picture 2 (Decoder)","accept":["KEYBOARD"]},{"label":"Picture 3 (Intel)","accept":["CLOUDCOMPUTING","CLOUDCOMPUTER"]}]'::jsonb, false, 5, 120, 'Say the emoji out loud and join the words.', 'SUNFLOWER: sun + flower | KEYBOARD: key + board | CLOUD COMPUTING: cloud + computer → cloud computing', null, 25, 'published'), ('recovery-pic-1', 'picture', 'recovery', 'Picture Riddles', 'picture', 1, array['any']::text[], 'Get back on your feet: two pictures make one word. Solve all three.', '{"scout":{"title":"Picture 1","body":"🐝 + 🍃","mono":false,"big":true},"decoder":{"title":"Picture 2","body":"🌊 + 🐎","mono":false,"big":true},"intel":{"title":"Picture 3","body":"🕷️ + 🕸️ + 🌐","mono":false,"big":true}}'::jsonb, '[{"label":"Picture 1 (Scout)","accept":["BAYLEAF","BEELEAF"]},{"label":"Picture 2 (Decoder)","accept":["SEAHORSE"]},{"label":"Picture 3 (Intel)","accept":["WORLDWIDEWEB","WEBSITE","WWW"]}]'::jsonb, false, 5, 120, 'Say the emoji out loud and join the words.', 'BAYLEAF: bee (bay) + leaf | SEAHORSE: sea + horse | WORLD WIDE WEB: the world-wide web', null, 25, 'published'), ('mission-riddle-0', 'riddle', 'mission', 'Riddle Room', 'riddle', 1, array['any','learning','office','social','hr','glass']::text[], 'Each teammate holds one riddle. Answer all three — one or two words each.', '{"scout":{"title":"Riddle 1","body":"I have keys but open no locks. I have space but no room. You can enter, but you can''t go inside.","mono":false,"big":false},"decoder":{"title":"Riddle 2","body":"The more you take, the more you leave behind.","mono":false,"big":false},"intel":{"title":"Riddle 3","body":"What has to be broken before you can use it?","mono":false,"big":false}}'::jsonb, '[{"label":"Riddle 1 (Scout)","accept":["KEYBOARD"]},{"label":"Riddle 2 (Decoder)","accept":["FOOTSTEPS","FOOTSTEP","STEPS"]},{"label":"Riddle 3 (Intel)","accept":["EGG","ANEGG"]}]'::jsonb, false, 3, 200, 'Think of everyday objects. Answers are short nouns.', 'KEYBOARD: a keyboard | FOOTSTEPS: footsteps | EGG: an egg', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now();
